-- Retention held back until a job is signed off: a percentage (0 to 20) of the grand total, and the
-- day it was released (null while it is still held). Released retention falls due 30 days later.
ALTER TABLE invoice ADD COLUMN retention_pct DECIMAL(5, 2) DEFAULT 0 NOT NULL;
ALTER TABLE invoice ADD COLUMN retention_released_on DATE;
-- A credit note may be for more than its original still owes. What the original took of it is kept in
-- credit_applied (credit_retention of that cleared retention it held back); the rest is held on the
-- client's account as a payment naming the credit note (credit_note), which cannot be reversed.
ALTER TABLE invoice ADD COLUMN credit_applied DECIMAL(19, 2);
ALTER TABLE invoice ADD COLUMN credit_retention DECIMAL(19, 2) DEFAULT 0 NOT NULL;
UPDATE invoice SET credit_applied = credit_total WHERE credit_total IS NOT NULL;
ALTER TABLE payment ADD COLUMN credit_note BIGINT;
-- The standard retention (0 to 20 percent, 0 is none) new invoices for the client start with.
ALTER TABLE client ADD COLUMN retention_pct DECIMAL(5, 2) DEFAULT 0 NOT NULL;
-- The most retention an invoice holds back, in its currency; null is no cap.
ALTER TABLE invoice ADD COLUMN retention_cap DECIMAL(19, 2);
-- The day a sent invoice was written off as a bad debt (null when it was not): everything still owed
-- on it that day, late charges and retention included, is written off; it stops earning interest,
-- owes nothing and takes no more payments.
ALTER TABLE invoice ADD COLUMN written_off_on DATE;
-- How much of the retention has been released in all, in the invoice's currency. Null with a release
-- day is a release recorded before partial releases: everything that was held was released.
ALTER TABLE invoice ADD COLUMN retention_released_amount DECIMAL(19, 2);
package net.officefloor.hq.app.invoices;

